function textFormatPreviewLabel(p){
 if(p.bundle)return "▣";
 if(p.id==="h1")return "H1";
 if(p.id==="h2")return "H2";
 if(p.id==="task")return "✓";
 if(p.id==="merke")return "!";
 return "Aa";
}
