  window.addEventListener('keydown',e=>{if(e.key==='Alt')altDown=true},true);window.addEventListener('keyup',e=>{if(e.key==='Alt')altDown=false},true);window.addEventListener('blur',()=>{altDown=false;desktopPan=null});
