  const endDesk=()=>{desktopPan=null;VP()?.classList.remove('v108Pan')};window.addEventListener('mouseup',endDesk,true);window.addEventListener('auxclick',e=>{if(inEditor()&&e.button===1)e.preventDefault()},true);

