/* One delegated capture handler owns every move start before any legacy editor
   listener can rerender the pointer target. This is the authoritative V131 path. */
window.addEventListener('pointerdown',e=>{const p=e.target instanceof Element?e.target.closest('.v131MoveProxy'):null;if(!p)return;proxyDown(e,p.dataset.kind,p.dataset.id)},{capture:true,passive:false});
/* Mouse input gets its own screen-delta path. Browsers and trackpads do not
   always emit an identical PointerEvent stream during a native drag gesture. */
window.addEventListener('mousedown',e=>{const p=e.target instanceof Element?e.target.closest('.v131MoveProxy'):null;if(!p||e.button!==0||mouseDrag||!editor())return;const kind=p.dataset.kind,id=p.dataset.id,item=kind==='object'?canvasState.objects.find(x=>x.id===id):canvasState.vectors.find(x=>x.id===id);if(!item||item.locked)return;e.preventDefault();e.stopImmediatePropagation();selectDirect(kind,id);mouseDrag={kind,id,sx:e.clientX,sy:e.clientY,snap:clone(item),proxy:p,moved:false};document.body.classList.add('v131Dragging')},{capture:true,passive:false});
window.addEventListener('mousemove',e=>{const d=mouseDrag;if(!d)return;let dx=(e.clientX-d.sx)/view.z,dy=(e.clientY-d.sy)/view.z;if(!d.moved&&Math.hypot(dx,dy)<1.5)return;d.moved=true;e.preventDefault();e.stopImmediatePropagation();if(d.kind==='object'){const o=canvasState.objects.find(x=>x.id===d.id);if(!o)return;o.x=clamp(d.snap.x+dx,0,Math.max(0,canvasPageWidth()-o.w));o.y=clamp(d.snap.y+dy,0,Math.max(0,canvasPageHeight()-o.h));const el=document.querySelector(`.cobj[data-id="${CSS.escape(d.id)}"]`);if(el){el.style.left=o.x+'px';el.style.top=o.y+'px'}d.proxy.style.left=o.x+'px';d.proxy.style.top=(o.kind==='table'?o.y-33:o.y)+'px'}else{const v=canvasState.vectors.find(x=>x.id===d.id);if(!v)return;const b0=bounds(d.snap);dx=clamp(dx,-b0.x,canvasPageWidth()-(b0.x+b0.w));dy=clamp(dy,-b0.y,canvasPageHeight()-(b0.y+b0.h));moveVector(v,d.snap,dx,dy);vectorDOM(v);const b=bounds(v),pad=Math.max(7,Number(v.strokeWidth||2)*2);d.proxy.style.left=(b.x-pad)+'px';d.proxy.style.top=(b.y-pad)+'px'}try{markCanvasDirty(false)}catch(_){}},{capture:true,passive:false});
window.addEventListener('mouseup',e=>{const d=mouseDrag;if(!d)return;mouseDrag=null;document.body.classList.remove('v131Dragging');e.preventDefault();e.stopImmediatePropagation();if(d.moved){try{pushHistory()}catch(_){}}try{renderCanvasObjects();renderVectors();renderCanvasInspector();renderLayerList()}catch(_){}requestAnimationFrame(syncMoveProxies)},{capture:true,passive:false});
function syncMoveProxies(){
  const root=ROOT();if(!root||!editor()||!window.canvasState)return;root.querySelectorAll('.v126VectorDragProxy,.v129ShapeProxy,.v131MoveProxy').forEach(x=>x.remove());
  for(const o of canvasState.objects||[]){if(o.editing)continue;const p=document.createElement('div'),table=o.kind==='table';p.className='v131MoveProxy '+(table?'tableGrip ':'')+(o.locked?'locked':'');p.dataset.kind='object';p.dataset.id=o.id;p.style.left=o.x+'px';p.style.top=(table?o.y-33:o.y)+'px';p.style.width=(table?78:Math.max(16,o.w-(canvasState.selectedId===o.id?12:0)))+'px';p.style.height=(table?27:Math.max(16,o.h-(canvasState.selectedId===o.id?12:0)))+'px';p.style.zIndex=String(30000+(o.z||0));if(o.rotation&&!table){p.style.transform=`rotate(${o.rotation}deg)`;p.style.transformOrigin='50% 50%'}p.addEventListener('pointerdown',e=>proxyDown(e,'object',o.id),{passive:false});root.appendChild(p)}
  for(const v of canvasState.vectors||[]){const b=bounds(v),pad=Math.max(7,Number(v.strokeWidth||2)*2),p=document.createElement('div');p.className='v131MoveProxy '+(v.locked?'locked':'');p.dataset.kind='vector';p.dataset.id=v.id;p.style.left=(b.x-pad)+'px';p.style.top=(b.y-pad)+'px';p.style.width=Math.max(18,b.w+pad*2)+'px';p.style.height=Math.max(18,b.h+pad*2)+'px';p.style.zIndex=String(30000+(v.z||0));if(v.rotation){p.style.transform=`rotate(${v.rotation}deg)`;p.style.transformOrigin=((b.cx-(b.x-pad))/(b.w+pad*2)*100)+'% '+((b.cy-(b.y-pad))/(b.h+pad*2)*100)+'%'}p.addEventListener('pointerdown',e=>proxyDown(e,'vector',v.id),{passive:false});root.appendChild(p)}
}

function pair(e){const a=e.touches[0],b=e.touches[1];return{cx:(a.clientX+b.clientX)/2,cy:(a.clientY+b.clientY)/2,d:Math.max(1,Math.hypot(a.clientX-b.clientX,a.clientY-b.clientY))}}
function bindGestures(){const vp=VP();if(!vp||vp.dataset.v131Gestures)return;vp.dataset.v131Gestures='1';
  vp.addEventListener('touchstart',e=>{if(!editor()||e.touches.length!==2)return;const q=pair(e),r=vp.getBoundingClientRect(),fx=q.cx-r.left,fy=q.cy-r.top;e.preventDefault();e.stopImmediatePropagation();activeDrag=null;gesture={d:q.d,z:view.z,wx:(fx-view.x)/view.z,wy:(fy-view.y)/view.z};document.body.classList.add('v131Panning')},{capture:true,passive:false});
  vp.addEventListener('touchmove',e=>{if(!gesture||e.touches.length!==2)return;const q=pair(e),r=vp.getBoundingClientRect(),fx=q.cx-r.left,fy=q.cy-r.top,z=clamp(gesture.z*q.d/gesture.d,.18,4);e.preventDefault();e.stopImmediatePropagation();view.z=z;view.x=fx-gesture.wx*z;view.y=fy-gesture.wy*z;view.touched=true;applyView()},{capture:true,passive:false});
  const touchEnd=e=>{if(!e.touches||e.touches.length<2){gesture=null;document.body.classList.remove('v131Panning')}};vp.addEventListener('touchend',touchEnd,{capture:true,passive:true});vp.addEventListener('touchcancel',touchEnd,{capture:true,passive:true});
  vp.addEventListener('wheel',e=>{if(!editor()||mobile()||!e.altKey)return;e.preventDefault();e.stopImmediatePropagation();zoomAt(view.z*Math.exp(-e.deltaY*.0018),e.clientX,e.clientY)},{capture:true,passive:false});
  vp.addEventListener('mousedown',e=>{if(!editor()||mobile()||!(e.button===1||(e.button===0&&space)))return;e.preventDefault();e.stopImmediatePropagation();pan={x:e.clientX,y:e.clientY,vx:view.x,vy:view.y};document.body.classList.add('v131Panning')},{capture:true});
  window.addEventListener('mousemove',e=>{if(!pan)return;view.x=pan.vx+(e.clientX-pan.x);view.y=pan.vy+(e.clientY-pan.y);view.touched=true;applyView()},true);
  const panEnd=()=>{pan=null;document.body.classList.remove('v131Panning')};window.addEventListener('mouseup',panEnd,true);window.addEventListener('blur',panEnd);vp.addEventListener('auxclick',e=>{if(e.button===1)e.preventDefault()});
}
window.addEventListener('keydown',e=>{if(!editor())return;const a=e.target instanceof Element?e.target:document.activeElement,typing=/INPUT|TEXTAREA|SELECT/.test(a?.tagName)||a?.isContentEditable||!!a?.closest?.('[contenteditable="true"]');if(e.code==='Space'&&!typing){space=true;document.body.classList.add('v131Space');e.preventDefault();return}if(typing)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='g'){e.preventDefault();e.shiftKey?ungroupSelectedItems():groupSelectedItems();return}if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelectedCanvasItem();return}if(/^Arrow/.test(e.key)){e.preventDefault();const dx=e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0,dy=e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0,step=e.shiftKey?10:1;canvasState.objects.filter(o=>(canvasState.selectedIds||[]).includes(o.id)&&!o.locked).forEach(o=>{o.x=clamp(o.x+dx*step,0,canvasPageWidth()-o.w);o.y=clamp(o.y+dy*step,0,canvasPageHeight()-o.h)});canvasState.vectors.filter(v=>(canvasState.selectedVectorIds||[]).includes(v.id)&&!v.locked).forEach(v=>{const s=clone(v);moveVector(v,s,dx*step,dy*step)});renderCanvasObjects();renderVectors();markCanvasDirty(false)}});
window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;document.body.classList.remove('v131Space')}});window.addEventListener('blur',()=>{space=false;document.body.classList.remove('v131Space')});

window.v131TableRowColor=function(value){const o=canvasState.objects.find(x=>x.id===canvasState.selectedId);if(!o||o.kind!=='table')return;const r=clamp(o.activeCell?.r||0,0,o.rows-1);o.cellColors||=Array.from({length:o.rows},()=>Array(o.cols).fill(''));while(o.cellColors.length<o.rows)o.cellColors.push(Array(o.cols).fill(''));o.cellColors[r]=Array(o.cols).fill(value);renderCanvasObjects();renderCanvasInspector();markCanvasDirty();pushHistory()};
window.v131TableColColor=function(value){const o=canvasState.objects.find(x=>x.id===canvasState.selectedId);if(!o||o.kind!=='table')return;const c=clamp(o.activeCell?.c||0,0,o.cols-1);o.cellColors||=Array.from({length:o.rows},()=>Array(o.cols).fill(''));for(let r=0;r<o.rows;r++){o.cellColors[r]||=[];while(o.cellColors[r].length<o.cols)o.cellColors[r].push('');o.cellColors[r][c]=value}renderCanvasObjects();renderCanvasInspector();markCanvasDirty();pushHistory()};
window.v131StripeTable=function(){const o=canvasState.objects.find(x=>x.id===canvasState.selectedId);if(!o||o.kind!=='table')return;o.cellColors=Array.from({length:o.rows},(_,r)=>Array.from({length:o.cols},()=>r%2?'#fff7f4':'#f3f8e9'));renderCanvasObjects();renderCanvasInspector();markCanvasDirty();pushHistory()};
function enhanceInspector(){const host=document.getElementById('canvasInspector');if(!host||!canvasState?.selectedId)return;const arrange=document.createElement('div');arrange.className='v131ArrangePanel';arrange.innerHTML='<div class="v131PanelTitle">Anordnen <span>Canva-Werkzeuge</span></div><div class="v131ActionGrid"><button onclick="duplicateSelected()">⧉<small>Duplizieren</small></button><button onclick="moveSelectedLayer(1)">↑<small>Nach vorn</small></button><button onclick="moveSelectedLayer(-1)">↓<small>Nach hinten</small></button><button onclick="toggleSelectedLock()">⌾<small>Sperren</small></button><button onclick="alignSelected(\'centerX\')">↔<small>Mittig</small></button><button onclick="alignSelected(\'centerY\')">↕<small>Zentrieren</small></button><button onclick="groupSelectedItems()">▣<small>Gruppieren</small></button><button onclick="deleteSelectedCanvasItem()">×<small>Löschen</small></button></div>';host.prepend(arrange);
  const o=canvasState.selectedType==='object'?canvasState.objects.find(x=>x.id===canvasState.selectedId):null;if(o?.kind==='table'){const r=clamp(o.activeCell?.r||0,0,o.rows-1),c=clamp(o.activeCell?.c||0,0,o.cols-1),rowColor=o.cellColors?.[r]?.find(Boolean)||o.cellBackground||'#ffffff',colColor=o.cellColors?.find(row=>row?.[c])?.[c]||o.cellBackground||'#ffffff',box=document.createElement('div');box.className='v131TableTools';box.innerHTML=`<div class="v131PanelTitle">Tabelle gestalten <span>Zeile ${r+1} · Spalte ${c+1}</span></div><div class="v131TableGrid"><label>Zeile einfärben<input type="color" value="${rowColor==='transparent'?'#ffffff':rowColor}" onchange="v131TableRowColor(this.value)"></label><label>Spalte einfärben<input type="color" value="${colColor==='transparent'?'#ffffff':colColor}" onchange="v131TableColColor(this.value)"></label><label>Kontur<select onchange="updateSelectedTable('borderStyle',this.value)"><option value="solid" ${o.borderStyle!=='dashed'&&o.borderStyle!=='dotted'?'selected':''}>Durchgezogen</option><option value="dashed" ${o.borderStyle==='dashed'?'selected':''}>Gestrichelt</option><option value="dotted" ${o.borderStyle==='dotted'?'selected':''}>Gepunktet</option></select></label><label>Ecken · ${o.borderRadius??12}px<input type="range" min="0" max="60" value="${o.borderRadius??12}" onchange="updateSelectedTable('borderRadius',+this.value)"></label></div><div class="v131TableButtons"><button onclick="v131StripeTable()">Zebra-Farben</button><button onclick="v131TableRowColor('transparent')">Zeile transparent</button></div>`;arrange.after(box)}
}
const oldInspector=window.renderCanvasInspector;window.renderCanvasInspector=function(){const r=oldInspector.apply(this,arguments);enhanceInspector();return r};try{renderCanvasInspector=window.renderCanvasInspector}catch(_){}

function layerIcon(ref,kind){if(kind==='vector')return ref?.shapeKind==='star'?'☆':ref?.type==='ellipse'?'○':ref?.type==='triangle'?'△':ref?.type==='path'?'〰':'□';return({text:'T',block:'▤',task:'☑',merke:'!',table:'▦',image:'▧',sticker:'✿',formula:'∑',graph:'⌁',paper:'▤',tape:'▰',file:'⌕'}[ref?.kind]||'◇')}
function reorderLayerV131(source,target,after){let all=layerEntries(),from=all.findIndex(x=>x.kind===source.kind&&x.id===source.id);if(from<0)return;const item=all.splice(from,1)[0],at=all.findIndex(x=>x.kind===target.kind&&x.id===target.id);if(at<0)return;all.splice(at+(after?1:0),0,item);const n=all.length;all.forEach((x,i)=>{const ref=layerItemRef(x.kind,x.id);if(ref)ref.z=(n-i)*10});renderCanvasObjects();renderVectors();renderLayerList();markCanvasDirty();pushHistory()}
let layerPointer=null,layerMouse=null;
function layerTargetAt(x,y,source){const row=document.elementFromPoint(x,y)?.closest?.('.v131LayerRow');if(!row||row.dataset.layerId===source.id&&row.dataset.layerKind===source.kind)return null;const r=row.getBoundingClientRect();return{row,kind:row.dataset.layerKind,id:row.dataset.layerId,after:y>r.top+r.height/2}}
function paintLayerDrop(t){document.querySelectorAll('.v131LayerRow').forEach(x=>x.classList.remove('drop-before','drop-after'));if(t)t.row.classList.add(t.after?'drop-after':'drop-before')}
window.addEventListener('pointerdown',e=>{const h=e.target instanceof Element?e.target.closest('.v131LayerRow .v130LayerHandle'):null;if(!h||e.pointerType==='mouse')return;const row=h.closest('.v131LayerRow');e.preventDefault();e.stopImmediatePropagation();layerPointer={pid:e.pointerId,source:{kind:row.dataset.layerKind,id:row.dataset.layerId},target:null};document.body.classList.add('layerDragging')},{capture:true,passive:false});
window.addEventListener('pointermove',e=>{if(!layerPointer||e.pointerId!==layerPointer.pid)return;e.preventDefault();e.stopImmediatePropagation();layerPointer.target=layerTargetAt(e.clientX,e.clientY,layerPointer.source);paintLayerDrop(layerPointer.target)},{capture:true,passive:false});
window.addEventListener('pointerup',e=>{if(!layerPointer||e.pointerId!==layerPointer.pid)return;e.preventDefault();e.stopImmediatePropagation();const d=layerPointer;layerPointer=null;document.body.classList.remove('layerDragging');paintLayerDrop(null);if(d.target)reorderLayerV131(d.source,d.target,d.target.after)},{capture:true,passive:false});
window.addEventListener('mousedown',e=>{const h=e.target instanceof Element?e.target.closest('.v131LayerRow .v130LayerHandle'):null;if(!h||e.button!==0)return;const row=h.closest('.v131LayerRow');e.preventDefault();e.stopImmediatePropagation();layerMouse={source:{kind:row.dataset.layerKind,id:row.dataset.layerId},target:null};document.body.classList.add('layerDragging')},{capture:true,passive:false});
window.addEventListener('mousemove',e=>{if(!layerMouse)return;e.preventDefault();e.stopImmediatePropagation();layerMouse.target=layerTargetAt(e.clientX,e.clientY,layerMouse.source);paintLayerDrop(layerMouse.target)},{capture:true,passive:false});
window.addEventListener('mouseup',e=>{if(!layerMouse)return;e.preventDefault();e.stopImmediatePropagation();const d=layerMouse;layerMouse=null;document.body.classList.remove('layerDragging');paintLayerDrop(null);if(d.target)reorderLayerV131(d.source,d.target,d.target.after)},{capture:true,passive:false});
function layerHTML(){const all=layerEntries();return `<div class="v131LayersHead">Ebenen <span>${all.length} Elemente</span></div><div class="v131LayerList">${all.length?all.map((a,i)=>{const ref=layerItemRef(a.kind,a.id);return `<div class="v130LayerRow v131LayerRow ${canvasState.selectedType===a.kind&&canvasState.selectedId===a.id?'active':''}" style="animation-delay:${Math.min(i*22,160)}ms" data-layer-kind="${a.kind}" data-layer-id="${a.id}"><button class="v130LayerHandle" title="Ziehen" aria-label="Ebene ziehen">⠿</button><button class="v130LayerTitle" onclick="${a.kind==='object'?`selectCanvasObject('${a.id}')`:`selectVector('${a.id}')`}"><span class="v131LayerTitleInner"><span class="v131LayerIcon">${layerIcon(ref,a.kind)}</span><span class="v131LayerText">${a.locked?'🔒 ':''}${esc(a.name)}</span></span></button><div class="v130LayerTools"><button title="Umbenennen" onclick="event.stopPropagation();renameLayerItem('${a.kind}','${a.id}')">✎</button><button title="${a.locked?'Entsperren':'Sperren'}" onclick="event.stopPropagation();${a.kind==='object'?`selectCanvasObject('${a.id}')`:`selectVector('${a.id}')`};toggleSelectedLock()">${a.locked?'🔓':'🔒'}</button><button class="danger" title="Löschen" onclick="event.stopPropagation();deleteLayerItem('${a.kind}','${a.id}')">×</button></div></div>`}).join(''):'<div class="small">Noch keine Elemente.</div>'}</div>`}
window.renderLayerList=function(){const html=layerHTML(),a=document.getElementById('layerList');if(a)a.innerHTML=html;const b=document.querySelector('#canvasQuickDrawer.open .mobileLayerList');if(b)b.innerHTML=html};try{renderLayerList=window.renderLayerList}catch(_){}

