        try{save()}catch(_){try{localStorage.setItem(KEY,JSON.stringify(data))}catch(__){}}
        try{renderPlan()}catch(_){};try{renderHome()}catch(_){};try{if(q('#view-subjects.active'))renderSubjects()}catch(_){}
